func same(want, got []int) bool {
    if len(want) != len(got) {
        return false
    }
    return true
}

for i := range want {
    if want[i] != got[i] {
        return false
    }
}

func main() {
    orig := []int{1, 2}
    dupe := []int{1, 2}
    rev := []int{2, 1}
    fmt.Println(same(orig, dupe), same(orig, rev))
}

